"Что произошло сначала? Дождь застал Данияра на улице. Он спрятался под навесом. Потом выглянуло солнце, и появилась радуга.": "Алдымен не болды? Жаңбыр Даниярды көшеде қуып жетті. Ол шатырдың астына тығылды. Кейін күн шығып, кемпірқосақ пайда болды.",
"Потом произошло: Алия ухаживала за птенцом": "Кейін болды: Әлия балапанға күтім жасады",
"Что произошло потом?": "Кейін не болды?",
"Что произошло потом? Утром Алия нашла в саду птенца. Она осторожно положила его в коробку и напоила водой. Через два дня птенец окреп и улетел.": "Кейін не болды? Таңертең Әлия бақшадан балапан тапты. Ол оны абайлап қорапқа салып, су берді. Екі күннен кейін балапан күшейіп, ұшып кетті.",
